/**
 * farmasiQueueSync — adapter tipis: kirim event antrian dari MORBIS ke App Antrian
 * (Reports SIMRS). App = source of truth nomor/status; extension hanya menangkap.
 *
 * BASE APP (prod, nested di dev.rsudkotajambi.id):
 *   - App penuh Reports SIMRS  : http://dev.rsudkotajambi.id/rs
 *   - Display antrian farmasi  : http://dev.rsudkotajambi.id/rs/antrian-farmasi
 *   - API antrian              : http://dev.rsudkotajambi.id/rs/api/queue/*
 * Override via localStorage 'ext-farmasi-app-base' (untuk tes lintas env, mis.
 * DDEV: http://simrs-reports.ddev.site).
 */
import { sendMessage } from '../../shared/messaging';

export const FARMASI_APP_BASE = 'http://dev.rsudkotajambi.id/rs';

export type QueueEventType = 'ENQUEUE' | 'CALL' | 'RECALL' | 'SKIP' | 'DONE' | 'TUNDA' | 'BATAL';

export interface QueueEventPayload {
  event_id: string;
  /** Opsional — utk ENQUEUE TIDAK dikirim (app assign T-XX/R-XX per jenis). */
  queue_number?: string;
  event: QueueEventType;
  counter?: string;
  operator_id?: number;
  resep_id?: string;
  nama_pasien?: string;
  norm?: string;
  tgl_lahir?: string;
  shift?: string;
  jenis?: string;
  payload?: Record<string, unknown>;
}

/** BASE app — localStorage override utk tes; fallback konstanta PROD. */
let cachedBase: string | null = null;
let basePromise: Promise<string> | null = null;

/** Kandidat dari daftar URL yang didaftarkan user di popup (extensionCustomUrls,
 *  chrome.storage.sync) — tiap URL MORBIS serve /rs juga. Ini sumber utama;
 *  konstanta PROD hanya fallback terakhir. */
async function storedBaseCandidates(): Promise<string[]> {
  try {
    const result = (await chrome.storage.sync.get('extensionCustomUrls')) as {
      extensionCustomUrls?: { url?: string; enabled?: boolean }[];
    };
    const urls = (result.extensionCustomUrls ?? []).filter((u) => u.url && u.enabled !== false);
    return urls.map((u) => (u.url as string).replace(/\/+$/, '') + '/rs');
  } catch {
    return [];
  }
}

const FALLBACK_CANDIDATES = ['http://dev.rsudkotajambi.id/rs', 'http://103.147.236.138/rs'];

/** Fetch API antrian via service worker — PNA-immune. SW punya host_permissions
 *  (semua http/https) dan tidak berjalan dari konteks halaman publik, jadi fetch
 *  ke server lokal/privat (mis. 192.168.8.4) dari halaman http://103.x TIDAK
 *  diblokir PNA. Balas { ok, status, contentType, data } supaya caller tetap bisa
 *  menolak host SPA (return 200 HTML, bukan JSON) seperti fetch langsung. */
// ponytail: cast supaya TS generic gak error (pre-existing sendMessage typing issue)
type QAResult = { ok: boolean; status?: number; contentType?: string; data?: unknown };
async function queueApiFetch(url: string, method: string, body?: unknown): Promise<QAResult> {
  return sendMessage({ type: 'QUEUE_API', url, method, body } as never) as Promise<QAResult>;
}

function withTimeout<T>(p: Promise<T>, ms: number): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const tid = setTimeout(() => reject(new Error('timeout')), ms);
    p.then((v) => {
      clearTimeout(tid);
      resolve(v);
    }).catch((e) => {
      clearTimeout(tid);
      reject(e);
    });
  });
}

/** Probe base mana yang hidup (GET /api/queue/lookup?resep_id= kosong → 422
 *  artinya app reachable). Hasil di-cache per sesi. */
export function farmasiAppBase(): string {
  try {
    const ov = localStorage.getItem('ext-farmasi-app-base');
    if (ov && /^https?:\/\//.test(ov)) {
      const b = ov.replace(/\/+$/, '');
      if (cachedBase !== b) {
        cachedBase = b;
        basePromise = null;
      }
      return b;
    }
  } catch {
    /* ignore */
  }
  if (cachedBase) return cachedBase;
  // Konstanta PROD — dev.rsudkotajambi.id resolve ke server Reports yang sama
  // (103.147.236.138) dari LAN maupun publik. JANGAN pakai origin + '/rs':
  // host MORBIS (192.168.8.4, 103.147.236.140) adalah SPA yang return 200
  // HTML utk path apa pun — bukan app Reports.
  return FARMASI_APP_BASE;
}

/** Probe semua kandidat base (daftar URL popup + fallback), kembalikan yang
 *  live (singkat). */
export function probeFarmasiAppBase(): Promise<string> {
  if (basePromise) return basePromise;
  basePromise = (async (): Promise<string> => {
    try {
      const ov = localStorage.getItem('ext-farmasi-app-base');
      if (ov && /^https?:\/\//.test(ov)) return ov.replace(/\/+$/, '');
    } catch {
      /* ignore */
    }
    const stored = await storedBaseCandidates();
    const candidates = [...new Set([...stored, ...FALLBACK_CANDIDATES])];
    for (const base of candidates) {
      try {
        // Lewat service worker (QUEUE_API) — fetch langsung dari halaman publik
        // ke server lokal/privat diblokir PNA; SW kebal PNA via host_permissions.
        const r = await withTimeout(
          queueApiFetch(base + '/api/queue/lookup?resep_id=probe', 'GET'),
          2500,
        );
        // App hidup = status 200/422 DAN body JSON. Host MORBIS (SPA) juga
        // return 200 untuk path apa pun, tapi HTML — harus ditolak.
        const ct = r.contentType || '';
        if ((r.status === 200 || r.status === 422) && ct.includes('application/json')) {
          cachedBase = base;
          return base;
        }
      } catch {
        /* coba kandidat berikutnya */
      }
    }
    return FARMASI_APP_BASE;
  })();
  return basePromise;
}

// ponytail: dedup repeated warn — "Failed to fetch" floods console when farmasi app is down.
let lastWarnMsg = '';

/** POST event ke app antrian. Idempoten (event_id unik) — aman dipanggil ganda.
 *  ENQUEUE: JANGAN kirim queue_number — app yang assign (T-XX/R-XX per jenis);
 *  nomor hasil ada di return.queue_number (dipakai cetak kartu). */
export async function pushQueueEvent(
  p: QueueEventPayload,
): Promise<{ ok: boolean; queue_number?: string; created?: boolean; duplicate?: boolean }> {
  try {
    const body: Record<string, unknown> = { ...p };
    if (p.event === 'ENQUEUE') delete body.queue_number;
    // BATAL perlu nomor antrian utk resolve (resolveExisting by queue_number).
    if (p.event === 'BATAL' && !p.queue_number) {
      console.warn('[MORBIS Ext] BATAL tanpa queue_number — dilewati');
      return { ok: false };
    }
    // Probe base sekali (ringan) supaya fallback IP dipakai bila DNS domain
    // internal RS tidak resolve.
    const base = await probeFarmasiAppBase();
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 8000);
    const res = await fetch(base + '/api/queue/events', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      cache: 'no-store',
      credentials: 'omit',
      signal: ctrl.signal,
    });
    clearTimeout(t);
    if (!res.ok) {
      let detail = '';
      try {
        detail = (await res.json())?.message || '';
      } catch {
        /* ignore */
      }
      throw new Error('HTTP ' + res.status + (detail ? ' — ' + detail : ''));
    }
    const j = (await res.json()) as {
      ok?: boolean;
      created?: boolean;
      duplicate?: boolean;
      queue?: { queue_number?: string };
    };
    return {
      ok: !!j.ok,
      queue_number: j.queue?.queue_number,
      created: j.created,
      duplicate: j.duplicate,
    };
  } catch (e) {
    const msg = (e as Error).message;
    // ponytail: "Failed to fetch" = farmasi app server tidak terjangkau —
    // bukan bug extension, tapi server down/DNS/CORS. Warn sekali saja.
    if (msg !== lastWarnMsg) {
      console.warn('[MORBIS Ext] queue sync gagal:', msg);
      lastWarnMsg = msg;
    }
    // Simpan ke retry queue supaya bisa dikirim ulang saat server up.
    await saveToRetryQueue(p);
    return { ok: false };
  }
}

/* ── Retry Queue (chrome.storage.local) ─────────────────────────────── */

const RETRY_KEY = 'ext-queue-retry-queue';
const MAX_RETRY_ITEMS = 20; // batasi supaya storage tidak membesar

/** Simpan event gagal ke retry queue. */
async function saveToRetryQueue(p: QueueEventPayload): Promise<void> {
  try {
    const existing = (await chrome.storage.local.get(RETRY_KEY))[RETRY_KEY] ?? [];
    // Dedupe by event_id — jangan simpan event yang sama 2x
    if (existing.some((item: QueueEventPayload) => item.event_id === p.event_id)) return;
    existing.push(p);
    // Batasi jumlah item
    if (existing.length > MAX_RETRY_ITEMS) existing.shift();
    await chrome.storage.local.set({ [RETRY_KEY]: existing });
    console.log('[MORBIS Ext] disimpan ke retry queue:', p.event, p.queue_number ?? '');
  } catch {
    // storage gagal — biarkan event hilang
  }
}

/** Ambil semua pending events dari retry queue. */
async function getRetryQueue(): Promise<QueueEventPayload[]> {
  try {
    return (await chrome.storage.local.get(RETRY_KEY))[RETRY_KEY] ?? [];
  } catch {
    return [];
  }
}

/** Hapus satu event dari retry queue berdasarkan event_id. */
async function removeFromRetryQueue(eventId: string): Promise<void> {
  try {
    const existing = (await chrome.storage.local.get(RETRY_KEY))[RETRY_KEY] ?? [];
    const filtered = existing.filter((item: QueueEventPayload) => item.event_id !== eventId);
    await chrome.storage.local.set({ [RETRY_KEY]: filtered });
  } catch {
    /* ignore */
  }
}

/** Flush retry queue — coba kirim ulang semua pending events.
 *  404/422 = event basi (record hilang / transisi ilegal) → hapus dari queue
 *  supaya tidak retry tiap 10 detik. Error lain (network/500) → biarkan. */
async function flushRetryQueue(): Promise<void> {
  const pending = await getRetryQueue();
  if (!pending.length) return;
  for (const item of [...pending]) {
    try {
      const result = await pushQueueEventDirect(item);
      if (result.ok) {
        await removeFromRetryQueue(item.event_id);
        console.log('[MORBIS Ext] retry queue sukses:', item.event, item.queue_number ?? '');
      }
    } catch (e: unknown) {
      const msg = (e as Error).message ?? '';
      // 404 = record tidak ada; 422 = transisi ilegal — keduanya = event basi
      if (msg.includes('HTTP 404') || msg.includes('HTTP 422')) {
        await removeFromRetryQueue(item.event_id);
        console.log(
          '[MORBIS Ext] retry queue buang (stale):',
          item.event,
          item.queue_number ?? '',
          msg,
        );
      }
      // network/500/timeout — biarkan di queue utk retry berikutnya
    }
  }
}

/** pushQueueEvent tanpa retry (untuk flushRetryQueue, hindari infinite loop).
 *  Melempar Error dengan message "HTTP {status}" supaya caller bisa bedakan
 *  transisi ilegal (422) dari network error. */
async function pushQueueEventDirect(
  p: QueueEventPayload,
): Promise<{ ok: boolean; queue_number?: string }> {
  const body: Record<string, unknown> = { ...p };
  if (p.event === 'ENQUEUE') delete body.queue_number;
  const base = await probeFarmasiAppBase();
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 8000);
  const res = await fetch(base + '/api/queue/events', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    cache: 'no-store',
    credentials: 'omit',
    signal: ctrl.signal,
  });
  clearTimeout(t);
  if (!res.ok) throw new Error('HTTP ' + res.status);
  const j = (await res.json()) as { ok?: boolean; queue?: { queue_number?: string } };
  return { ok: !!j.ok, queue_number: j.queue?.queue_number };
}

// Auto-flush tiap 10 detik
setInterval(() => void flushRetryQueue(), 10000);

/** event_id deterministik dari sumber (idVisit/resepId + nomor) — stabil utk retry. */
export function queueEventId(prefix: string, source: string, nomor: string): string {
  return `${prefix}-${source}-${nomor}-${new Date().toISOString().slice(0, 10)}`;
}

/** Gate fitur antrian farmasi: jalankan cb HANYA jika fitur aktif (attribute
 *  data-ext-antrian-farmasi di-set init.ts bila feature enabled + role
 *  diizinkan). Polling singkat karena content script bisa jalan sebelum
 *  init.ts selesai loadConfig (document_start / satu entry dengan init.js).
 *  ponytail: polling 200ms max 5s — kalau init.ts lambat, fitur di-skip
 *  + tampilkan notifikasi ke user. */
export function whenAntrianFarmasiActive(cb: () => void, timeoutMs = 5000): void {
  const el = document.documentElement;
  const t0 = Date.now();
  const iv = window.setInterval(() => {
    if (el.getAttribute('data-ext-antrian-farmasi') === '1') {
      window.clearInterval(iv);
      cb();
    } else if (Date.now() - t0 > timeoutMs) {
      window.clearInterval(iv);
      // Tampilkan notifikasi ke user agar tahu fitur tidak aktif
      showFeatureGateNotif();
    }
  }, 200);
}

/** Tampilkan banner kecil di pojok kanan atas saat fitur antrian tidak aktif. */
function showFeatureGateNotif(): void {
  if (document.getElementById('ext-feature-gate-notif')) return; // sudah ada
  const banner = document.createElement('div');
  banner.id = 'ext-feature-gate-notif';
  banner.textContent = '⚠️ Fitur antrian tidak aktif — muat ulang halaman (F5)';
  banner.style.cssText =
    'position:fixed;top:8px;right:8px;z-index:999999;background:#dc3545;color:#fff;' +
    'padding:8px 16px;border-radius:6px;font:13px system-ui,sans-serif;box-shadow:0 2px 8px rgba(0,0,0,.2);';
  document.body.appendChild(banner);
  setTimeout(() => banner.remove(), 10000);
}
